// ===============================================================================
// DAEMIND SRE - FILTRO ANTI-LOOP E EXTRAÇÃO DE CONTEXTO DO CHATWOOT
// ===============================================================================
const body = $json.body || $json;

// 1. Validação de evento: Processa apenas mensagens INCOMING (do cliente) e NÃO privadas
const messageType = body.message_type || (body.event === 'message_created' ? body.message_type : '');
const isPrivate = Boolean(body.private);
const isIncoming = messageType === 'incoming' || body.event === 'message_created' && messageType === 0;

if (isPrivate || !isIncoming) {
  return [{
    json: {
      should_process: false,
      reason: 'Mensagem enviada por atendente/bot ou é nota privada. Ignorando para evitar loop.'
    }
  }];
}

const content = (body.content || '').trim();
if (!content) {
  return [{
    json: {
      should_process: false,
      reason: 'Mensagem sem conteúdo textual.'
    }
  }];
}

const conversationId = body.conversation?.id || body.conversation_id || 1;
const accountId = body.account?.id || body.account_id || 1;
const sender = body.sender || {};
const contactName = (sender.name || 'Cliente').trim();
const rawPhone = (sender.phone_number || '').toString().replace(/\D/g, '');
const email = (sender.email || '').trim().toLowerCase();

return [{
  json: {
    should_process: true,
    conversation_id: conversationId,
    account_id: accountId,
    cliente_nome: contactName,
    cliente_telefone: rawPhone,
    cliente_email: email,
    mensagem_cliente: content,
    created_at: body.created_at || Date.now()
  }
}];

// ===============================================================================
// DAEMIND SRE - COMPILADOR DE RAG, MEMÓRIA HISTÓRICA E DIRETRIZES DE IA
// ===============================================================================
const clienteData = $('Filtrar e Sanitizar Mensagem').item.json;
const ragData = $('Recuperar RAG e Dados do Cliente (PostgreSQL)').item.json;
const rawMessages = $json.payload || [];

// 1. Extração e montagem da memória das últimas 6 mensagens
const historicoMensagens = rawMessages
  .filter(m => !m.private && m.content)
  .slice(-6)
  .map(m => `[${m.message_type === 0 ? 'Cliente' : 'Atendente IA'}]: ${m.content}`)
  .join('\n');

// 2. Compilação de dados de RAG (Pedidos recentes + FAQ da Empresa)
const pedidosContexto = JSON.stringify(ragData.pedidos_contexto || []);
const faqContexto = JSON.stringify(ragData.rag_politicas || []);

const systemPrompt = `Você é o Especialista de Atendimento Autônomo da empresa. Seu objetivo é atender ${clienteData.cliente_nome} com cordialidade, precisão e elegância.

### DIRETRIZES DE ATENDIMENTO:
1. Responda de forma direta, acolhedora e concisa (máximo 2 a 3 parágrafos curtos).
2. Utilize as informações de RAG fornecidas abaixo para tirar dúvidas reais sobre pedidos, rastreio, estoque e políticas da empresa.
3. Se o cliente solicitar explicitamente um atendente humano, estiver visivelmente irritado, ou se você não tiver certeza absoluta sobre a resposta, acione o Human Handoff (handoff_humano: true).

### CONTEXTO DE RAG DA EMPRESA:
- Pedidos Recentes do Cliente: ${pedidosContexto}
- Políticas e FAQs Corporativas: ${faqContexto}

### HISTÓRICO RECENTE DA CONVERSA (MEMÓRIA):
${historicoMensagens}

### FORMATO ESTRITO DE RESPOSTA:
Responda ESTRITAMENTE em formato JSON com as chaves:
- 'resposta_cliente': (Texto formatado em markdown WhatsApp para enviar ao cliente)
- 'handoff_humano': (Booleano: true se precisa transferir para humano, false se resolvido por IA)
- 'motivo_handoff': (String explicando o motivo caso handoff_humano seja true)
- 'resumo_atendente': (Síntese concisa de 2 linhas para a equipe interna)`;

return [{
  json: {
    system_prompt: systemPrompt,
    mensagem_atual: clienteData.mensagem_cliente,
    conversation_id: clienteData.conversation_id,
    account_id: clienteData.account_id,
    cliente_nome: clienteData.cliente_nome
  }
}];

// ===============================================================================
// DAEMIND SRE - PARSER DE RESPOSTA E DECISÃO DE HANDOFF
// ===============================================================================
const rawContent = $json.choices?.[0]?.message?.content || '{}';
let parsed = {};

try {
  const cleanJson = rawContent.replace(/```json\n?|```/g, '').trim();
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = {
    resposta_cliente: 'Olá! Recebi sua mensagem e estou transferindo para um de nossos atendentes especialistas para te ajudar da melhor forma.',
    handoff_humano: true,
    motivo_handoff: 'Falha no parse do LLM',
    resumo_atendente: 'Cliente enviou mensagem. Transcrição manual requerida.'
  };
}

const comp = $('Compilar RAG e Prompt').item.json;
const isHandoff = Boolean(parsed.handoff_humano);

const notaPrivada = `🤖 **DAEMIND AI - RESUMO DE TRANSIÇÃO HUMAN HANDOFF**\n\n👤 **Cliente:** ${comp.cliente_nome}\n🎯 **Motivo:** ${parsed.motivo_handoff || 'Solicitação do cliente ou complexidade alta'}\n📝 **Resumo do Caso:** ${parsed.resumo_atendente || 'Cliente aguardando suporte humano no chat.'}\n💡 **Status:** Atendimento transferido para a fila humana.`;

return [{
  json: {
    ...parsed,
    is_handoff: isHandoff,
    nota_privada_formatada: notaPrivada,
    account_id: comp.account_id,
    conversation_id: comp.conversation_id,
    cliente_nome: comp.cliente_nome
  }
}];

